parameters.content:
{
  "id": "109bf8d2-ebf8-4070-acad-657e308fef97",
  "version": "1.8",
  "name": "VendorInvoiceProcessing",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "New Invoice Received"
      },
      "inputs": {
        "entryPointId": "af270587-a843-4b5d-a835-110b37d43118",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "extractInvoiceFields",
      "type": "core.logic.mock",
      "typeVersion": "1.0",
      "display": {
        "label": "Extract Invoice Fields (mock — publish Vendor Invoices IXP model first)"
      }
    },
    {
      "id": "parseExtractionResults",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Parse Extraction Results"
      },
      "inputs": {
        "script": "// Reads the IxP extraction output and surfaces the fields you need\n// After the IXP mock is replaced with the real node, the extraction result\n// will be at $vars.extractInvoiceFields.output.ExtractionResult.ResultsDocument\nconst extractionOutput = $vars.extractInvoiceFields.output;\n\n// When the real IXP node is wired, use:\n// const fields = extractionOutput.ExtractionResult.ResultsDocument.Fields || [];\n// const tables = extractionOutput.ExtractionResult.ResultsDocument.Tables || [];\n// For now the mock returns null — this script returns a structured placeholder.\nconst fields = (extractionOutput && extractionOutput.ExtractionResult)\n  ? extractionOutput.ExtractionResult.ResultsDocument.Fields || []\n  : [];\n\nconst getField = (name) => {\n  const f = fields.find(f => f.FieldName === name);\n  return f ? (f.Values && f.Values[0] !== undefined ? f.Values[0] : null) : null;\n};\n\n// Header fields\nconst invoiceNumber = getField('Invoice Number');\nconst vendorName   = getField('Vendor Name');\nconst invoiceDate  = getField('Invoice Date');\nconst totalAmount  = getField('Total Amount');\n\n// Line items come from Tables[]\nconst lineItemsTable = (extractionOutput && extractionOutput.ExtractionResult)\n  ? (extractionOutput.ExtractionResult.ResultsDocument.Tables || [])\n      .find(t => t.TableId === 'Vendor Invoice > Line Items')\n  : null;\n\nconst lineItems = lineItemsTable\n  ? (lineItemsTable.Rows || []).map(row => ({\n      description : (row.Fields || []).find(f => f.FieldName === 'Description')  ?.Values?.[0] || null,\n      quantity    : (row.Fields || []).find(f => f.FieldName === 'Quantity')      ?.Values?.[0] || null,\n      unitPrice   : (row.Fields || []).find(f => f.FieldName === 'Unit Price')    ?.Values?.[0] || null,\n      lineTotal   : (row.Fields || []).find(f => f.FieldName === 'Line Total')    ?.Values?.[0] || null\n    }))\n  : [];\n\nreturn {\n  invoiceNumber,\n  vendorName,\n  invoiceDate,\n  totalAmount,\n  lineItems,\n  lineItemCount: lineItems.length\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "end",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Invoice Processed"
      },
      "outputs": {
        "invoiceNumber": {
          "source": "=js:$vars.parseExtractionResults.output.invoiceNumber"
        },
        "vendorName": {
          "source": "=js:$vars.parseExtractionResults.output.vendorName"
        },
        "invoiceDate": {
          "source": "=js:$vars.parseExtractionResults.output.invoiceDate"
        },
        "totalAmount": {
          "source": "=js:$vars.parseExtractionResults.output.totalAmount"
        },
        "lineItems": {
          "source": "=js:$vars.parseExtractionResults.output.lineItems"
        },
        "lineItemCount": {
          "source": "=js:$vars.parseExtractionResults.output.lineItemCount"
        }
      }
    }
  ],
  "edges": [
    {
      "id": "edge-start-extract",
      "sourceNodeId": "start",
      "sourceHandle": "output",
      "targetNodeId": "extractInvoiceFields",
      "targetPort": "input"
    },
    {
      "id": "edge-extract-parse",
