  "nodes": [
    {
      "id": "extractInvoiceFields1",
      "type": "core.logic.mock",
      "typeVersion": "1.0",
      "display": {
        "label": "Extract Invoice Fields (mock — publish InvoiceProcessing IXP model first)"
      }
    },
    {
      "id": "parseExtractionResults1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Parse Extraction Results"
      },
      "inputs": {
        "script": "// Reads IXP extraction output and returns structured invoice fields.\n// When the real IXP node replaces the mock, the extraction result lives at:\n//   $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument\nconst extractionOutput = $vars.extractInvoiceFields1.output;\n\nconst fields = (extractionOutput && extractionOutput.ExtractionResult)\n  ? extractionOutput.ExtractionResult.ResultsDocument.Fields || []\n  : [];\n\nconst getField = (name) => {\n  const f = fields.find(f => f.FieldName === name);\n  return f ? (f.Values && f.Values[0] !== undefined ? f.Values[0] : null) : null;\n};\n\nconst invoiceNumber = getField('Invoice Number');\nconst vendorName   = getField('Vendor Name');\nconst invoiceDate  = getField('Invoice Date');\nconst totalAmount  = getField('Total Amount');\n\n// Line items are in Tables[]\nconst lineItemsTable = (extractionOutput && extractionOutput.ExtractionResult)\n  ? (extractionOutput.ExtractionResult.ResultsDocument.Tables || [])\n      .find(t => t.TableId === 'Vendor Invoice > Line Items')\n  : null;\n\nconst lineItems = lineItemsTable\n  ? (lineItemsTable.Rows || []).map(row => ({\n      description : (row.Fields || []).find(f => f.FieldName === 'Description') ? (row.Fields || []).find(f => f.FieldName === 'Description').Values[0] : null,\n      quantity    : (row.Fields || []).find(f => f.FieldName === 'Quantity')    ? (row.Fields || []).find(f => f.FieldName === 'Quantity').Values[0]    : null,\n      unitPrice   : (row.Fields || []).find(f => f.FieldName === 'Unit Price')  ? (row.Fields || []).find(f => f.FieldName === 'Unit Price').Values[0]   : null,\n      lineTotal   : (row.Fields || []).find(f => f.FieldName === 'Line Total')  ? (row.Fields || []).find(f => f.FieldName === 'Line Total').Values[0]   : null\n    }))\n  : [];\n\nreturn { invoiceNumber: invoiceNumber, vendorName: vendorName, invoiceDate: invoiceDate, totalAmount: totalAmount, lineItems: lineItems, lineItemCount: lineItems.length };"
      }
    },
    {
      "id": "end1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Invoice Processed"
      }
    },
